INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(94568601, 'Tyrant Dragon', '暴君龙', 'タイラント・ドラゴン', 'Effect Monster', 'Dragon', 'FIRE', 8, 2900, 2500, '只在对方场上有怪兽存在的场合才在战斗阶段中只再1次可以攻击。此外，以这张卡为对象的陷阱卡无效并破坏。其他卡的效果把这张卡从墓地特殊召唤的场合，必须把自己场上1只龙族怪兽作为祭品。'),
(90814668, 'Tyrant Farm', '暴君种植场', 'タイラント・プランテーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1只效果怪兽解放才能发动。从自己墓地选原本的种族·属性和那只怪兽相同的1只效果怪兽以外的怪兽特殊召唤。'),
(16172067, 'Tyrant Red Dragon Archfiend', '暗红恶魔龙・暴君', 'レッド・デーモンズ・ドラゴン・タイラント', 'Synchro Monster', 'Dragon', 'DARK', 10, 3500, 3000, '调整2只＋调整以外的怪兽1只以上 这张卡不用同调召唤不能特殊召唤。「红莲魔龙·暴君」的①②的效果1回合各能使用1次。 ①：自己主要阶段1才能发动。这张卡以外的场上的卡全部破坏。这个回合，这张卡以外的自己怪兽不能攻击。 ②：战斗阶段有魔法·陷阱卡发动时才能发动。那个发动无效并破坏，这张卡的攻击力上升500。'),
(57470761, 'Tyrant Wing', '暴君翼', 'タイラント・ウィング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只龙族怪兽为对象才能把这张卡发动。这张卡当作攻击力·守备力上升400的装备卡使用给那只怪兽装备。 ②：用这张卡的效果把这张卡装备的怪兽在同1次的战斗阶段中最多2次可以向怪兽攻击。 ③：用这张卡的效果把这张卡装备的怪兽向对方怪兽攻击的回合的结束阶段发动。这张卡破坏。'),
(38318146, 'Tyrant''s Tantrum', '暴君的暴力', '暴君の暴力', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上存在的2只怪兽解放发动。只要这张卡在场上存在，对方若不从卡组把1张魔法卡送去墓地则不能把魔法卡发动。'),
(4638410, 'Tyrant''s Temper', '暴君的威压', '暴君の威圧', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上存在的1只怪兽解放发动。只要这张卡在场上存在，场上表侧表示存在的原本持有者是自己的怪兽不受这张卡以外的陷阱卡的效果影响。'),
(55271628, 'Tyrant''s Throes', '暴君的自暴自弃', '暴君の自暴自棄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上存在的衍生物以外的2只通常怪兽解放发动。只要这张卡在场上存在，双方不能把效果怪兽召唤·特殊召唤。'),
(76721030, 'Tyrant''s Tirade', '暴君的暴言', '暴君の暴言', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上存在的2只怪兽解放发动。只要这张卡在场上存在，双方不能把手卡以及场上发动的效果怪兽的效果发动。'),
(48357738, 'Tyrant''s Tummyache', '暴君的暴饮暴食', '暴君の暴飲暴食', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '把自己场上存在的1只怪兽解放发动。只要这张卡在场上存在，双方不能把6星以上的怪兽特殊召唤。自己手卡是3张以上的场合，这张卡破坏。'),
(11819616, 'Tytannial, Princess of Camellias', '椿姬媞泰妮亚', '椿姫ティタニアル', 'Effect Monster', 'Plant', 'WIND', 8, 2800, 2600, '①：场上的卡为对象的魔法·陷阱·怪兽的效果发动时，把自己场上1只表侧表示的植物族怪兽解放才能发动。那个发动无效并破坏。'),
(34614289, 'U.A. Blockbacker', '超级运动员 强壮阻挡员', 'U.A.ストロングブロッカー', 'Effect Monster', 'Warrior', 'EARTH', 7, 1600, 2700, '「超级运动员 强壮阻挡员」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 强壮阻挡员」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：1回合1次，对方对怪兽的特殊召唤成功时才能发动。那些怪兽的表示形式变更，那个效果无效。'),
(71279983, 'U.A. Dreadnought Dunker', '超级运动员 无畏扣篮手', 'U.A.ドレッドノートダンカー', 'Effect Monster', 'Warrior', 'EARTH', 7, 2500, 1800, '「超级运动员 无畏扣篮手」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 无畏扣篮手」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡给与对方战斗伤害时，以场上1张卡为对象才能发动。那张卡破坏。'),
(9485511, 'U.A. Goalkeeper', '超级运动员 守门员', 'U.A.カストディアン', 'Effect Monster', 'Warrior', 'EARTH', 6, 1000, 2800, '「超级运动员 守门员」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 守门员」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：对方回合1次，以自己场上1只「超级运动员」怪兽为对象才能发动。那只怪兽在这个回合只有1次不会被战斗·效果破坏。'),
(12931061, 'U.A. Hyper Stadium', '超级运动员高超体育场', 'U.A.ハイパー・スタジアム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「方程式运动员」卡使用。这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「超级运动员」怪兽或者「方程式运动员」怪兽加入手卡或从自己墓地选1张「超级运动员体育场」加入手卡。 ②：把手卡1张场地魔法卡给对方观看，支付1000基本分才能发动。这个回合，自己在通常召唤外加上只有1次，可以把1只「超级运动员」怪兽或者「方程式运动员」怪兽召唤。'),
(11637481, 'U.A. Libero Spiker', '超级运动员 自由人攻手', 'U.A.リベロスパイカー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以让「超级运动员 自由人攻手」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：对方主要阶段才能发动。手卡1只5星以上的「超级运动员」怪兽回到卡组，和那只怪兽卡名不同的1只「超级运动员」怪兽从卡组特殊召唤。那之后，场上的这张卡回到持有者手卡。'),
(49936169, 'U.A. Locker Room', '超级运动员更衣室', 'U.A.ロッカールーム', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「方程式运动员」卡使用。这个卡名的卡在1回合只能发动1张。 ①：以自己的场上·墓地1只「超级运动员」怪兽或者「方程式运动员」怪兽为对象才能发动。那只怪兽回到持有者手卡，自己回复500基本分。那之后，以下效果可以适用。 ●手卡的「超级运动员」怪兽或者「方程式运动员」怪兽任意数量给对方观看，回到卡组洗切。那之后，自己从卡组抽出回到卡组的数量。'),
(48636108, 'U.A. Man of the Match', '超级运动员最佳球员', 'U.A.マン・オブ・ザ・マッチ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「方程式运动员」卡使用。这个卡名的卡在1回合只能发动1张。 ①：自己的「超级运动员」怪兽或者「方程式运动员」怪兽去用战斗破坏对方怪兽的伤害计算后或者去给与对方战斗伤害时才能发动。从自己的手卡·墓地选「超级运动员」怪兽以及「方程式运动员」怪兽任意数量守备表示特殊召唤（同名卡最多1张）。'),
(72491806, 'U.A. Midfielder', '超级运动员 九号半球员', 'U.A.ファンタジスタ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1200, 1000, '「超级运动员 九号半球员」的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以让「超级运动员 九号半球员」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：以这张卡以外的自己场上1只「超级运动员」怪兽为对象才能发动。那只表侧表示怪兽回到手卡，那之后把和那只怪兽卡名不同的1只「超级运动员」怪兽从手卡特殊召唤。这个效果在对方回合也能发动。'),
(56421754, 'U.A. Mighty Slugger', '超级运动员 猛力强击手', 'U.A.マイティスラッガー', 'Effect Monster', 'Warrior', 'EARTH', 5, 2300, 700, '「超级运动员 猛力强击手」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 猛力强击手」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。'),
(70043345, 'U.A. Penalty Box', '超级运动员受罚', 'U.A.ペナルティ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「超级运动员受罚」的①的效果1回合只能使用1次。 ①：自己的「超级运动员」怪兽和对方怪兽进行战斗的伤害步骤开始时才能把这个效果发动。那只对方怪兽直到发动后第2次的对方结束阶段除外。 ②：把墓地的这张卡除外才能发动。从卡组把1张「超级运动员」魔法卡加入手卡。'),
(82419869, 'U.A. Perfect Ace', '超级运动员 完美王牌投手', 'U.A.パーフェクトエース', 'Effect Monster', 'Warrior', 'EARTH', 5, 1500, 2500, '「超级运动员 完美王牌投手」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 完美王牌投手」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：对方回合1次，魔法·陷阱·怪兽的效果发动时，丢弃1张手卡才能发动。那个发动无效并破坏。'),
(47021196, 'U.A. Player Manager', '超级运动员 球员兼领队', 'U.A.プレイングマネージャー', 'Effect Monster', 'Warrior', 'EARTH', 8, 2000, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：自己对「超级运动员」怪兽的召唤·特殊召唤成功的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤成功的场合，可以从以下效果选择1个发动。 ●以场上1张卡为对象才能发动。那张卡破坏。 ●「超级运动员」怪兽以外的场上的全部表侧表示怪兽的效果直到回合结束时无效。'),
(98229575, 'U.A. Playmaker', '超级运动员 四分卫球员', 'U.A.フィールドゼネラル', 'Effect Monster', 'Warrior', 'EARTH', 8, 2600, 2000, '「超级运动员 四分卫球员」的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以让「超级运动员 四分卫球员」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：这张卡以外的自己的「超级运动员」怪兽的攻击宣言时才能发动。这张卡的攻击力下降800，自己的攻击怪兽的攻击力上升800。'),
(35884610, 'U.A. Powered Jersey', '超级运动员强化特训服', 'U.A.パワードギプス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '「超级运动员」怪兽才能装备。 ①：装备怪兽的攻击力·守备力上升1000，装备怪兽和对方怪兽进行战斗的场合，给与对方的战斗伤害变成2倍。 ②：装备怪兽的攻击破坏怪兽的场合才能发动。这次战斗阶段中，装备怪兽只再1次可以攻击。 ③：自己准备阶段发动。装备怪兽除外。 ④：装备怪兽回到手卡让这张卡被送去墓地的场合才能发动。这张卡回到手卡。'),
(17264592, 'U.A. Rival Rebounder', '超级运动员 角逐篮板手', 'U.A.コリバルリバウンダー', 'Effect Monster', 'Warrior', 'EARTH', 6, 2200, 2300, '「超级运动员 角逐篮板手」的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以让「超级运动员 角逐篮板手」以外的自己场上1只「超级运动员」怪兽回到手卡，从手卡特殊召唤。 ②：这张卡召唤或者对方回合中的特殊召唤成功的场合才能发动。从自己的手卡·墓地选「超级运动员 角逐篮板手」以外的1只「超级运动员」怪兽特殊召唤。'),
(43658697, 'U.A. Signing Deal', '超级运动员王牌转队', 'U.A.フラッグシップ・ディール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只「超级运动员」怪兽特殊召唤。这个效果特殊召唤的怪兽不能作为同调·超量召唤的素材，效果无效化。那之后，自己失去那只怪兽的等级×300基本分。'),
(19814508, 'U.A. Stadium', '超级运动员体育场', 'U.A.スタジアム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上有「超级运动员」怪兽召唤的场合才能发动。从卡组把1只「超级运动员」怪兽加入手卡。 ②：1回合1次，自己场上有「超级运动员」怪兽特殊召唤的场合发动。自己场上的怪兽的攻击力上升500。'),
(61613388, 'U.A. Turnover Tactics', '超级运动员换人战术', 'U.A.ターンオーバー・タクティクス', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「超级运动员换人战术」在1回合只能发动1张。 ①：自己场上有「超级运动员」怪兽2种类以上存在的场合才能发动。场上的怪兽全部回到持有者卡组。那之后，自己把最多有这个效果回到自己卡组的卡数量的「超级运动员」怪兽从卡组特殊召唤（同名卡最多1张）。这个效果让自己特殊召唤的怪兽在这个回合不能攻击。那之后，对方可以把最多有这个效果回到对方卡组的卡数量的怪兽从卡组特殊召唤。'),
(60806437, 'UFO Turtle', '飞碟龟', 'UFOタートル', 'Effect Monster', 'Machine', 'FIRE', 4, 1400, 1200, '这张卡被战斗破坏送去墓地时，可以从卡组把1只攻击力1500以下的炎属性怪兽表侧攻击表示特殊召唤。'),
(9275482, 'UFOLight', '幻日灯火', '幻日灯火', 'Effect Monster', 'Illusion', 'FIRE', 8, 1500, 1500, '这个卡名的③的效果1回合只能使用1次。 ①：战斗阶段以外，对方不能把场上的这张卡作为效果的对象。 ②：这张卡和怪兽进行战斗的场合，那2只不会被那次战斗破坏。 ③：自己·对方的结束阶段才能发动。自己抽1张。那之后，选自己手卡任意数量除外，这张卡的攻击力上升这个效果除外的卡数量×500。'),
(7602840, 'UFOroid', '飞碟机人', 'ユーフォロイド', 'Effect Monster', 'Machine', 'LIGHT', 6, 1200, 1200, '这张卡被战斗破坏送去墓地时，可以从卡组把1只攻击力1500以下的机械族怪兽表侧攻击表示特殊召唤，那之后卡组洗切。'),
(32752319, 'UFOroid Fighter', '飞碟机人战士', 'ユーフォロイド・ファイター', 'Fusion Monster', 'Machine', 'LIGHT', 10, -1, -1, '「飞碟机人」＋战士族怪兽 这只怪兽融合召唤只能用上记的卡进行。这张卡的原本的攻击力·守备力，变成融合素材的2只怪兽的原本的攻击力合计的数值。'),
(49451215, 'Ukanomitsune-no-Onari', '宇迦之御狐御成', 'うかのみつねのおなり', 'Link Monster', 'Beast', 'LIGHT', NULL, 1500, NULL, '包含兽族怪兽的光属性怪兽2只 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤的场合，以自己墓地1张速攻魔法卡为对象才能发动。那张卡在自己场上盖放。 ②：对方不能把场地区域的卡作为效果的对象。 ③：这张卡被破坏的场合才能发动。选最多有场地区域的卡数量的以下效果，那些效果适用（相同效果最多1个）。 ●对方场上1张卡破坏。 ●给与对方1500伤害。'),
(93413793, 'Ukanomitsune-no-Tamayura', '宇迦之御狐玉响', 'うかのみつねのたまゆら', 'Tuner Monster', 'Beast', 'LIGHT', 3, 1500, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有兽族·植物族·天使族而4星以下的光属性怪兽存在的场合才能发动。这张卡特殊召唤。 ②：这张卡为素材作同调召唤的怪兽得到以下效果。 ●这张卡的守备力上升500。 ●只要这张卡在怪兽区域守备表示存在，对方不能把这张卡作为效果的对象。'),
(44708154, 'Ukiyoe-P.U.N.K. Amazing Dragon', '浮－朋.克.惊龙', 'Uk－P.U.N.K.アメイジング・ドラゴン', 'Synchro Monster', 'Sea Serpent', 'WIND', 11, 3000, 2800, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡同调召唤的场合，以最多有自己的场上·墓地的念动力族·3星怪兽种类数量的对方场上的卡为对象才能发动。那些卡回到手卡。 ②：以「浮世绘朋克 惊龙」以外的自己墓地1只「朋克」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(18313046, 'Ukiyoe-P.U.N.K. Rising Carp', '浮－朋.克.鲤跃', 'Uk－P.U.N.K.カープ・ライジング', 'Fusion Monster', 'Fish', 'WATER', 8, 1000, 2600, '「朋克」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把融合召唤的这张卡解放才能发动。从手卡·卡组把最多2只8星以外的「朋克」怪兽守备表示特殊召唤（同名卡最多1张）。 ②：这张卡为同调素材作同调召唤的场合，以自己场上1只「朋克」怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(13258285, 'Ukiyoe-P.U.N.K. Sharakusai', '浮－朋.克.娑乐斋', 'Uk－P.U.N.K.娑楽斎', 'Tuner Monster', 'Psychic', 'EARTH', 3, 1200, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：支付600基本分才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「朋克」融合怪兽融合召唤。 ②：对方回合，支付600基本分才能发动。进行1只「朋克」同调怪兽的同调召唤。'),
(501000000, 'Ulevo', NULL, NULL, 'Effect Monster', 'Winged Beast', 'EARTH', 10, 3000, 2500, NULL),
(12652643, 'Ultimate Ancient Gear Golem', '古代机械齿轮究极巨人', '古代の機械究極巨人', 'Fusion Monster', 'Machine', 'EARTH', 10, 4400, 3400, '「古代的机械巨人」＋「古代的机械」怪兽×2 这张卡不用融合召唤不能特殊召唤。 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡被破坏的场合，以自己墓地1只「古代的机械巨人」为对象才能发动。那只怪兽无视召唤条件特殊召唤。'),
(40101111, 'Ultimate Axon Kicker', '究极超能者', 'アルティメットサイキッカー', 'Fusion Monster', 'Psychic', 'LIGHT', 10, 2900, 1700, '念动力族同调怪兽＋念动力族怪兽 这张卡用融合召唤才能从额外卡组特殊召唤。 ①：这张卡只要在怪兽区域存在，不会被效果破坏。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：这张卡战斗破坏怪兽送去墓地的场合发动。自己基本分回复那只怪兽的原本攻击力的数值。'),
(28736826, 'Ultimate Baseball Homerun King', '超热血本垒打王', '超熱血本塁打王', 'Effect Monster', 'Warrior', 'FIRE', 4, 1500, 300, '①：这张卡战斗破坏对方怪兽时才能发动。这张卡的攻击力上升1000。'),
(67934141, 'Ultimate Baseball Kid', '超热血球儿', '超熱血球児', 'Effect Monster', 'Warrior', 'FIRE', 3, 500, 1000, '场上有这张卡以外的炎属性怪兽存在的场合，每有1张，这张卡的攻击力上升1000。每把这张卡以外的1只炎属性怪兽送去墓地，给与对方基本分500分的伤害。'),
(14959144, 'Ultimate Bright Knight Ursatron Alpha', '天极辉士－熊斗龙巧阿尔法', '天極輝士－熊斗竜巧α', 'Effect Monster', 'Machine', 'WATER', 7, 2000, 700, '这个卡名在规则上也当作「北极天熊」卡、「龙辉巧」卡使用。这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的效果1回合只能使用1次。 ①：除「天极辉士-熊斗龙巧α」外的，「北极天熊」怪兽或「龙辉巧」怪兽在自己场上存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1张「北极天熊」魔法·陷阱卡或「龙辉巧」魔法·陷阱卡加入手卡。'),
(18940556, 'Ultimate Conductor Tyranno', '究极传导恐兽', '究極伝導恐獣', 'Effect Monster', 'Dinosaur', 'LIGHT', 10, 3500, 3200, '这张卡不能通常召唤。从自己墓地把2只恐龙族怪兽除外的场合可以特殊召唤。 ①：1回合1次，自己·对方的主要阶段才能发动。选自己的手卡·场上1只怪兽破坏，对方场上的表侧表示怪兽全部变成里侧守备表示。 ②：这张卡可以向对方怪兽全部各作1次攻击。 ③：这张卡向守备表示怪兽攻击的伤害步骤开始时才能发动。给与对方1000伤害，那只守备表示怪兽送去墓地。'),
(36328300, 'Ultimate Crystal Magic', '究极宝玉阵', '究極宝玉陣', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的「宝玉兽」怪兽被战斗破坏时，从手卡·卡组以及自己场上的表侧表示的卡之中把「宝玉兽」卡7种类各1张送去墓地才能发动。把1只「究极宝玉神」融合怪兽当作融合召唤从额外卡组特殊召唤。 ②：自己场上的表侧表示的「究极宝玉神」怪兽因对方的效果从场上离开的场合，把墓地的这张卡除外才能发动。选自己墓地的「宝玉兽」怪兽任意数量当作永续魔法卡使用在自己的魔法与陷阱区域表侧表示放置。'),
(84544192, 'Ultimate Crystal Rainbow Dragon Overdrive', '究极宝玉神 虹龙 超越', '究極宝玉神 レインボー・ドラゴン オーバー・ドライブ', 'Fusion Monster', 'Dragon', 'LIGHT', 12, 4000, NULL, '「究极宝玉神」怪兽＋「宝玉兽」怪兽×7 自己对「究极宝玉神」怪兽的特殊召唤成功的决斗中，把自己的场上·墓地的上记卡除外的场合才能特殊召唤。 ①：除外的自己的「宝玉兽」怪兽是7种类以上的场合，这张卡的攻击力上升7000。 ②：自己·对方回合，把这个回合没有进行战斗的这张卡解放才能发动。场上的卡全部回到持有者卡组，选除外的自己的「宝玉兽」怪兽任意数量特殊召唤。'),
(32247099, 'Ultimate Divine-Beast', '绝对之幻神兽', '絶対なる幻神獣', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时，从手卡丢弃1张魔法·陷阱卡，以自己墓地1只幻神兽族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。那之后，攻击对象转移为那只怪兽。 ②：自己场上有幻神兽族怪兽存在的场合，结束阶段才能发动。把这个回合在场上让效果发动的对方场上的表侧表示的卡全部破坏。'),
(3149401, 'Ultimate Dragon of Pride and Soul', '骄傲与灵魂之究极龙', '誇りと魂の究極竜', 'Fusion Monster', 'Dragon', 'DARK', 12, 4500, 4500, '原本攻击力和原本守备力是2500的怪兽×3 ①：只要融合召唤的这张卡在怪兽区域存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：只要自己墓地有卡25张以上存在，融合召唤的这张卡的攻击力·守备力上升4500。 ③：1回合1次，对方墓地有卡25张以上存在的场合才能发动。对方场上的卡全部破坏。'),
(75402014, 'Ultimate Dragonic Utopia Ray', '龙装合体 龙王霍普雷', '竜装合体 ドラゴニック・ホープレイ', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2500, 2000, '5星怪兽×3 这个卡名在规则上当作「混沌No.39 希望皇 霍普雷」使用。 ①：1回合1次，这张卡成为效果的对象时或者被选择作为攻击对象时才能发动。从手卡·卡组选1只「异热同心武器」怪兽当作那个效果的装备卡使用给这张卡装备。 ②：1回合1次，把这张卡1个超量素材取除，以最多有这张卡装备的「异热同心武器」怪兽卡数量的对方场上的表侧表示的卡为对象才能发动。那些卡的效果无效。'),
(70109009, 'Ultimate Earthbound Immortal', '究极地缚神', '究極地縛神', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：场上有通常召唤的「地缚神」怪兽存在的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。'),
(6713443, 'Ultimate Fire Formation - Seito', '极炎舞－星斗－', '極炎舞－「星斗」', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己墓地7张名字带有「炎舞」的魔法·陷阱卡从游戏中除外才能发动。从自己墓地把名字带有「炎星」的怪兽尽可能特殊召唤。那之后，可以从卡组选最多有这个效果特殊召唤的怪兽数量的「极炎舞-「星斗」」以外的名字带有「炎舞」的魔法·陷阱卡在自己场上盖放。'),
(55538156, 'Ultimate Fire Formation - Sinto', '极炎舞－辰斗－', '極炎舞－「辰斗」', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「炎星」怪兽以及「炎舞」魔法·陷阱卡存在，魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(33250142, 'Ultimate Flagship Ursatron', '天极辉舰－熊斗龙巧', '天極輝艦－熊斗竜巧', 'Fusion Monster', 'Machine', 'WATER', 7, 2000, 700, '这个卡名在规则上也当作「北极天熊」卡、「龙辉巧」卡使用。这张卡用「天斗辉巧极」的效果才能特殊召唤。 ①：1回合1次，自己场上有其他的效果怪兽特殊召唤的场合才能发动。从卡组把1只「北极天熊」怪兽或者「龙辉巧」怪兽加入手卡。 ②：1回合1次，以除外的1只自己的「北极天熊」怪兽或者「龙辉巧」怪兽为对象才能发动。那只怪兽加入手卡。'),
(324483, 'Ultimate Flame Swordsman', '极炎之剑士', '極炎の剣士', 'Fusion Monster', 'Warrior', 'FIRE', 8, 2800, 1600, '「炎之剑士」＋「斗气炎斩龙」 这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只怪兽为对象才能发动（这张卡有装备卡装备的场合，这个效果在对方回合也能发动）。那只怪兽破坏，给与对方500伤害。 ②：这张卡进行战斗的伤害步骤开始时才能发动。这张卡的攻击力直到回合结束时变成2倍。这个回合的结束阶段这张卡破坏。'),
(71143015, 'Ultimate Fusion', '究极结合', '究極融合', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的主要阶段才能发动。自己的手卡·场上·墓地的怪兽作为融合素材回到卡组，把以「青眼白龙」或「青眼究极龙」为融合素材的1只融合怪兽融合召唤。那之后，可以把最多有那些作为融合素材的场上的「青眼白龙」「青眼究极龙」数量的对方场上的表侧表示卡破坏。'),
(87804747, 'Ultimate Great Insect', '完全态大昆虫', '完全態・グレート・インセクト', 'Fusion Monster', 'Insect', 'EARTH', 9, 3000, 2600, '昆虫族·8星怪兽＋昆虫族·7星怪兽 自己对「完全态大昆虫」1回合只能有1次特殊召唤。这张卡用融合召唤以及以下方法才能从额外卡组特殊召唤。 ●把有装备卡装备的1只自己的守备力2000以上的昆虫族怪兽解放的场合可以从额外卡组特殊召唤。 ①：这张卡不会被战斗破坏。 ②：场地区域有表侧表示卡存在的场合，自己·对方的战斗阶段才能发动1次。对方场上的怪兽全部破坏。'),
(49441499, 'Ultimate Insect LV1', '究极昆虫 LV1', 'アルティメット・インセクト LV１', 'Effect Monster', 'Insect', 'WIND', 1, NULL, NULL, '自己场上表侧表示存在的这张卡不会受到魔法的效果影响。自己回合的准备阶段时，可以把表侧表示的这张卡送到墓地，从手卡·卡组特殊召唤1只「究极昆虫 LV3」。（召唤·特殊召唤·反转的回合不能使用此效果）'),
(34088136, 'Ultimate Insect LV3', '究极昆虫 LV3', 'アルティメット・インセクト LV３', 'Effect Monster', 'Insect', 'WIND', 3, 1400, 900, '「究极昆虫 LV1」的效果特殊召唤的场合，只要这张卡在场上存在，对方全部怪兽的攻击力下降300。自己回合的准备阶段时，可以把表侧表示的这张卡送去墓地，从卡组·手卡特殊召唤1只「究极昆虫 LV5」。（召唤·特殊召唤·反转的回合不能使用此效果）'),
(34830502, 'Ultimate Insect LV5', '究极昆虫 LV5', 'アルティメット・インセクト LV５', 'Effect Monster', 'Insect', 'WIND', 5, 2300, 900, '「究极昆虫 LV3」的效果特殊召唤的场合，只要这张卡在场上存在，对方场上的全部怪兽攻击力下降500。自己回合的准备阶段时，可以把表侧表示的这张卡送去墓地，从手卡·卡组特殊召唤1只「究极昆虫 LV7」上场。（召唤·特殊召唤·反转的回合不能使用此效果）'),
(19877898, 'Ultimate Insect LV7', '究极昆虫 LV7', 'アルティメット・インセクト LV７', 'Effect Monster', 'Insect', 'WIND', 7, 2600, 1200, '「究极昆虫 LV5」的效果特殊召唤的场合，只要这张卡在自己场上存在，对方的全部怪兽攻击力·守备力下降700。'),
(68679595, 'Ultimate Leo Utopia Ray', '兽装合体 狮王霍普雷', '獣装合体 ライオ・ホープレイ', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2500, 2000, '5星怪兽×3 这个卡名在规则上当作「混沌No.39 希望皇 霍普雷」使用。 ①：1回合1次，把这张卡1个超量素材取除才能发动（这个效果的发动和效果不会被无效化）。从卡组·额外卡组选1只「异热同心武器」怪兽当作那个效果的装备魔法卡使用给这张卡装备。 ②：双方回合1次，这张卡有「异热同心武器」怪兽卡装备的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效，那个攻击力变成一半。'),
(32240937, 'Ultimate Obedient Fiend', '绝对服从魔人', '絶対服従魔人', 'Effect Monster', 'Fiend', 'FIRE', 10, 3500, 3000, '当自己场上只有这张卡存在且自己手卡数为零时这张卡才能进行攻击。被这张卡破坏的效果怪兽的效果无效化。'),
(80604092, 'Ultimate Offering', '血之代偿', '血の代償', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, NULL),
(38891741, 'Ultimate Providence', '神之摄理', '神の摂理', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：怪兽的效果·魔法·陷阱卡发动时，把和那个效果相同种类（怪兽·魔法·陷阱）的1张卡从手卡丢弃才能发动。那个发动无效并破坏。'),
(2263869, 'Ultimate Slayer', '月女神之镞', '月女神の鏃', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方不能对应这张卡的发动把怪兽的效果发动。 ①：从额外卡组把1只怪兽送去墓地，以和那只怪兽相同种类（融合·同调·超量·灵摆·连接）的对方场上1只怪兽为对象才能发动。那只怪兽回到卡组。'),
(15894048, 'Ultimate Tyranno', '究极恐兽', '究極恐獣', 'Effect Monster', 'Dinosaur', 'EARTH', 8, 3000, 2200, '①：自己战斗阶段有可以攻击的「究极恐兽」存在的场合，「究极恐兽」以外的怪兽不能攻击。 ②：这张卡可以向对方怪兽全部各作1次攻击。'),
(1686814, 'Ultimaya Tzolkin', '究极玛雅・卓尔金', 'アルティマヤ・ツィオルキン', 'Synchro Monster', 'Dragon', 'DARK', NULL, NULL, NULL, '规则上，这张卡的等级当作12星使用。这张卡不能同调召唤，把自己场上的表侧表示的5星以上而相同等级的调整和调整以外的怪兽各1只送去墓地的场合才能特殊召唤。 ①：1回合1次，自己场上有魔法·陷阱卡被盖放时才能发动。把1只「动力工具」同调怪兽或者7·8星的龙族同调怪兽从额外卡组特殊召唤。 ②：场上的这张卡只要其他的自己的同调怪兽存在，不会成为攻击对象以及效果的对象。'),
(76823930, 'Ultimeat Offering', '血肉之代偿', '血肉の代償', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段支付1000基本分才能发动。这个回合，自己可以进行通常召唤最多3次。 ②：对方战斗阶段支付500基本分才能发动。进行1只怪兽的召唤。'),
(50855622, 'Ultra Beetrooper Absolute Hercules', '超骑甲虫 绝对赫克力士', '超騎甲虫アブソリュート・ヘラクレス', 'Fusion Monster', 'Insect', 'EARTH', 11, 4000, 4000, '昆虫族怪兽×4 这个卡名的②的效果1回合只能使用1次。 ①：这张卡融合召唤成功的场合，这张卡直到下次的自己回合的结束时不受其他卡的效果影响。 ②：自己·对方的战斗阶段结束时，以自己墓地1只攻击力3000以下的昆虫族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(22431243, 'Ultra Evolution Pill', '超进化药', '超進化薬', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '祭掉自己场上1只爬虫类族怪兽。从手卡特殊召唤1只恐龙族怪兽上场。'),
(76647978, 'Ultra Polymerization', '超越融合', '超越融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让卡的效果发动。 ①：支付2000基本分才能发动。自己场上的怪兽2只作为融合素材，把1只融合怪兽融合召唤。 ②：把墓地的这张卡除外，以这张卡的效果融合召唤的1只怪兽为对象才能发动。那只怪兽的融合召唤使用过的一组融合素材怪兽从自己墓地特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0，效果无效化。'),
(59708927, 'Umbral Horror Ghost', '阴影幽鬼', 'アンブラル・ゴースト', 'Effect Monster', 'Fiend', 'DARK', 2, 200, 200, '自己的主要阶段时才能发动。这张卡和1只4星以下的恶魔族怪兽从手卡特殊召唤。这个效果发动的回合，自己不能通常召唤。「阴影幽鬼」的效果1回合只能使用1次。'),
(7152333, 'Umbral Horror Ghoul', '阴影食尸鬼', 'アンブラル・グール', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, NULL, '1回合1次，自己的主要阶段时才能发动。这张卡的攻击力变成0，从手卡把1只攻击力0的名字带有「阴影」的怪兽特殊召唤。'),
(67949764, 'Umbral Horror Mirage Token', '罪键之法', '罪鍵の法－シン・キー・ロウ', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(33551032, 'Umbral Horror Unform', '阴影无形鬼', 'アンブラル・アンフォーム', 'Effect Monster', 'Fiend', 'DARK', 4, NULL, NULL, '这张卡的攻击让这张卡被战斗破坏送去墓地时，可以从卡组把2只名字带有「阴影」的怪兽特殊召唤。「阴影无形鬼」的效果1回合只能使用1次。'),
(70546737, 'Umbral Horror Will o'' the Wisp', '阴影鬼火', 'アンブラル・ウィル・オ・ザ・ウィスプ', 'Effect Monster', 'Fiend', 'DARK', 1, NULL, NULL, '这张卡召唤·特殊召唤成功时，选择这张卡以外的自己的场上·墓地1只名字带有「阴影」的怪兽才能发动。这张卡的等级变成和选择的怪兽的等级相同。此外，场上表侧攻击表示存在的这张卡被战斗破坏送去墓地时，把让这张卡破坏的怪兽破坏。'),
(86229493, 'Umbral Soul', '暗冥之魂', 'ダークネスソウル', 'Effect Monster', 'Reptile', 'DARK', 7, 2000, 1500, '这张卡被战斗破坏送去墓地时，场上表侧表示存在的暗属性怪兽以外的怪兽全部破坏。'),
(59281822, 'Umbramirage the Elemental Lord', '暗灵神 翁布雷密拉热', '闇霊神オブルミラージュ', 'Effect Monster', 'Fiend', 'DARK', 8, 2800, 2200, '这张卡不能通常召唤。自己墓地的暗属性怪兽是5只的场合才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤成功的场合发动。从卡组把1只攻击力1500以下的怪兽加入手卡。 ②：表侧表示的这张卡从场上离开的场合，下次的自己回合的战斗阶段跳过。'),
(22702055, 'Umi', '海', '海', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部鱼族·海龙族·雷族·水族的怪兽攻击力·守备力上升200。机械族·炎族的怪兽攻击力·守备力下降200。'),
(82999629, 'Umiiruka', '水世界', 'ウォーターワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '全部的水属性的怪兽攻击力上升500，守备力下降400。'),
(30464153, 'Uminotaurus', '海牛头人', 'ウミノタウルス', 'Effect Monster', 'Aqua', 'WATER', 4, 1700, 1000, '只要这张卡在场上表侧表示存在，自己场上的鱼族·海龙族·水族怪兽向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。'),
(4072687, 'Unacceptable Result', '难以接受的结果', '受け入れがたい結果', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己场上有魔法师族怪兽存在的场合才能发动。从手卡把1只「占卜魔女」怪兽特殊召唤。'),
(81951640, 'Unauthorized Bootup Device', '奇动装置 恣动机', '奇動装置メイルファクター', 'Union Effect Monster', 'Machine', 'DARK', 1, 500, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：给怪兽装备的这张卡被破坏送去墓地的场合才能发动。这张卡特殊召唤。'),
(12524259, 'Unauthorized Reactivation', '恣动机群指令・再奇动', '無許可の再奇動', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只机械族怪兽为对象才能发动。那只怪兽把可以装备的1只机械族同盟怪兽从手卡·卡组装备。这个效果装备的同盟怪兽在这个回合不能特殊召唤。'),
(88494120, 'Unbreakable Spirit', '不屈的斗志', '不屈の闘志', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的表侧表示怪兽只有1只的场合，以那1只怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升对方场上的攻击力最低的怪兽的攻击力数值。'),
(96004535, 'Unbreakable Xyz Barrier', '超量不屈屏障', 'エクシーズ・アンブレイカブル・バリア', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有超量怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效。那之后，可以把自己场上2个超量素材取除。那个场合，再把场上1张卡破坏。 ②：把墓地的这张卡除外，以自己场上1只超量怪兽为对象才能发动。从自己墓地把1只光属性「霍普」超量怪兽作为成为对象的怪兽的超量素材。'),
(29479265, 'Unchained Abomination', '破械双王神 来迎', '破械雙王神ライゴウ', 'Link Monster', 'Fiend', 'DARK', NULL, 3000, NULL, '包含连接怪兽的怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：「破械双王神 来迎」以外的卡的效果让场上的卡被破坏的场合，以场上1张卡为对象才能发动。那张卡破坏。 ②：这张卡以外的怪兽被战斗破坏时，以场上1张卡为对象才能发动。那张卡破坏。 ③：自己·对方的结束阶段以场上1张卡为对象才能发动。那张卡破坏。'),
(24269961, 'Unchained Soul Lord of Yama', '破械神王 阎魔', '破械神王ヤマ', 'Link Monster', 'Fiend', 'DARK', NULL, 2000, NULL, '恶魔族怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1只「破械」怪兽加入手卡。 ②：这张卡在墓地存在的状态，自己场上的卡被战斗·效果破坏的场合，把这张卡除外才能发动。从自己的手卡·墓地把1只恶魔族怪兽特殊召唤。那之后，可以把自己场上1张卡破坏。'),
(93084621, 'Unchained Soul of Anguish', '破械神 安若磐', '破械神アルバ', 'Link Monster', 'Fiend', 'DARK', NULL, 2400, NULL, '包含「破械神」怪兽的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽为对象才能发动。只用那只对方怪兽和自己场上的这张卡为素材把「破械神 阿罗魃」以外的1只暗属性连接怪兽连接召唤。 ②：场上的这张卡被战斗·效果破坏的场合，以「破械神 阿罗魃」以外的自己墓地1只恶魔族怪兽为对象才能发动。那只怪兽加入手卡。'),
(89019964, 'Unchained Soul of Disaster', '破械神之祸灵', '破械神の禍霊', 'Effect Monster', 'Fiend', 'DARK', 8, NULL, 3000, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升自己墓地的「破械」卡数量×300。 ②：以对方场上1只表侧表示怪兽为对象才能发动。只用那只对方怪兽和自己场上的这张卡为素材把1只暗属性连接怪兽连接召唤。 ③：场上的这张卡被战斗·效果破坏的场合，以「破械神的祸灵」以外的自己墓地1只「破械」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(67680512, 'Unchained Soul of Rage', '破械神 拉基安', '破械神ラギア', 'Link Monster', 'Fiend', 'DARK', NULL, 1800, NULL, '包含「破械神」怪兽的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：对方主要阶段，以对方场上1只特殊召唤的表侧表示怪兽为对象才能发动。只用那只对方怪兽和自己场上的这张卡为素材把「破械神 罗寂刹」以外的1只暗属性连接怪兽连接召唤。 ②：场上的这张卡被战斗·效果破坏的场合，以「破械神 罗寂刹」以外的自己墓地1只恶魔族怪兽为对象才能发动。那只怪兽加入手卡。'),
(41165831, 'Unchained Soul of Sharvara', '破械神 奢婆罗', '破械神シャバラ', 'Effect Monster', 'Fiend', 'FIRE', 6, 2000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，自己·对方的主要阶段，以自己场上1只恶魔族怪兽或1张里侧表示卡为对象才能发动。那张卡破坏，这张卡特殊召唤。只要这个效果特殊召唤的这张卡在怪兽区域表侧表示存在，自己不是恶魔族怪兽不能特殊召唤。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「破械」魔法·陷阱卡在自己场上盖放。'),
(88554436, 'Unchained Soul of Shyama', '破械神 修耶摩', '破械神シュヤーマ', 'Effect Monster', 'Fiend', 'WATER', 6, 2000, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张卡为对象才能发动。那张卡破坏。那之后，可以把场上1张魔法·陷阱卡破坏。 ②：这张卡在墓地存在的场合，以自己场上1只恶魔族怪兽或1张里侧表示卡为对象才能发动。那张卡破坏，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合回到卡组最下面。'),
(26236560, 'Unchained Twins - Aruha', '破械童子 安若般', '破械童子アルハ', 'Effect Monster', 'Fiend', 'FIRE', 3, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张卡为对象才能发动。那张卡破坏，这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。 ②：场上的这张卡被战斗或者「破械童子 阿罗汉」以外的卡的效果破坏的场合才能发动。从手卡·卡组把「破械童子 阿罗汉」以外的1只「破械」怪兽特殊召唤。'),
(53624265, 'Unchained Twins - Rakea', '破械童子 拉奇安', '破械童子ラキア', 'Effect Monster', 'Fiend', 'WATER', 3, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张卡为对象才能发动。那张卡破坏。这个效果的发动后，直到回合结束时自己不是恶魔族怪兽不能特殊召唤。这个效果在对方回合也能发动。 ②：场上的这张卡被战斗或者「破械童子 罗鬼刹」以外的卡的效果破坏的场合才能发动。从手卡·卡组把「破械童子 罗鬼刹」以外的1只「破械」怪兽特殊召唤。'),
(31588572, 'Unchained Twins - Sarama', '破械童子 娑罗摩', '破械童子サラマ', 'Effect Monster', 'Fiend', 'DARK', 3, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以「破械童子 娑罗摩」以外的自己墓地1张「破械」卡为对象才能发动。那张卡在自己场上盖放。那之后，选自己场上1张卡破坏。 ②：场上的这张卡被战斗或者「破械童子 娑罗摩」以外的卡的效果破坏的场合才能发动。从手卡·卡组把「破械童子 娑罗摩」以外的1只「破械」怪兽特殊召唤。'),
(8700633, 'Undaunted Bumpkin Beast', '不屈的兽仆', '不屈の獣僕', 'Effect Monster', 'Beast', 'FIRE', 2, 900, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：对方把3只以上的怪兽特殊召唤的回合的主要阶段才能发动。这张卡从手卡·墓地特殊召唤。这个效果在对方回合也能发动。 ②：自己场上没有其他怪兽存在的场合，攻击表示的这张卡不会被战斗破坏。'),
(300302055, 'Under Pressure', NULL, NULL, 'Skill Card', 'Bastion Misaw', NULL, NULL, NULL, NULL, NULL),
(77058170, 'Underclock Taker', '降频承办机', 'アンダークロックテイカー', 'Link Monster', 'Cyberse', 'DARK', NULL, 1000, NULL, '效果怪兽2只 ①：1回合1次，以这张卡所连接区1只表侧表示怪兽和对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力直到回合结束时下降作为对象的所连接区的怪兽的攻击力数值。'),
(5779502, 'Underdog', '形势反转', '形勢反転', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己回合内，对方场上的表侧表示怪兽的效果无效化，对方回合内，自己场上的表侧表示怪兽的效果无效化。'),
(63465535, 'Underground Arachnid', '地底之阿剌克涅', '地底のアラクネー', 'Synchro Monster', 'Insect', 'EARTH', 6, 2400, 1200, '暗属性调整＋调整以外的昆虫族怪兽1只 这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。1回合1次，可以选择对方场上表侧表示存在的1只怪兽当作装备卡使用只有1只给这张卡装备。这张卡被战斗破坏的场合，可以作为代替把这个效果装备的怪兽破坏。'),
(51324455, 'Underworld Egg Clutch', '魔制产卵床', '魔製産卵床', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的鱼族·海龙族·水族怪兽从游戏中除外时才能发动。从自己卡组把1只4星以下的鱼族·海龙族·水族怪兽加入手卡。'),
(52639377, 'Underworld Fighter Balmung', '魔界斗士 屠龙之剑', '魔界闘士 バルムンク', 'Synchro Monster', 'Warrior', 'DARK', 4, 2100, 800, '调整＋调整以外的怪兽1只以上 这张卡被卡的效果破坏送去墓地时，可以从自己墓地选择这张卡以外的1只4星以下的怪兽特殊召唤。'),
(98127546, 'Underworld Goddess of the Closed World', '闭界冥神 蚀日的埃列丝', '閉ザサレシ世界ノ冥神', 'Link Monster', 'Fiend', 'LIGHT', NULL, 3000, NULL, '效果怪兽4只以上 这张卡连接召唤的场合，对方场上1只怪兽也能作为连接素材。 ①：这张卡连接召唤的场合才能发动。对方场上的全部表侧表示怪兽的效果无效化。 ②：连接召唤的这张卡不受除以这张卡为对象的效果以外的对方发动的效果影响。 ③：1回合1次，包含从墓地把怪兽特殊召唤效果的魔法·陷阱·怪兽的效果由对方发动时才能发动。那个发动无效。'),
(8428836, 'Underworld Ritual of Prediction', '冥占术的仪式', '冥占術の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「占术姬」仪式怪兽的降临必需。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的怪兽解放，从自己的手卡·墓地把1只「占术姬」仪式怪兽表侧攻击表示或者里侧守备表示仪式召唤。 ②：自己场上有「占术姬」仪式怪兽存在的场合，自己·对方的准备阶段把墓地的这张卡除外才能发动。从卡组把仪式怪兽以外的1只「占术姬」怪兽里侧守备表示特殊召唤。'),
(69452756, 'Unending Nightmare', '无法唤醒的噩梦', '醒めない悪夢', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的效果在同一连锁上只能发动1次。 ①：支付1000基本分，以场上1张表侧表示的魔法·陷阱卡为对象才能把这个效果发动。那张卡破坏。'),
(911883, 'Unexpected Dai', '不速怪客', '予想GUY', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在的场合才能发动。从卡组把1只4星以下的通常怪兽特殊召唤。'),
(38180759, 'Unformed Void', '虚构王 无形巨洞', '虚構王アンフォームド・ボイド', 'XYZ Monster', 'Aqua', 'LIGHT', 4, NULL, NULL, '4星怪兽×3 对方的主要阶段时1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力·守备力上升对方场上的超量怪兽的攻击力合计数值。'),
(22318971, 'Uni-Horned Familiar', '独角兽使魔', '一角獣の使い魔', 'Tuner Monster', 'Beast', 'LIGHT', 2, NULL, 1000, '表侧守备表示存在的这张卡被选择作为攻击对象时，可以把这张卡以外的自己场上存在的1只怪兽从游戏中除外，把这张卡从游戏中除外。那个时候的攻击怪兽必须作出攻击。这个效果除外的这张卡在下次的自己的准备阶段时回到场上。'),
(12743620, 'Uni-Song Tuning', '齐唱调整', 'ユニゾン・チューン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己或者对方的墓地1只调整和场上1只表侧表示怪兽为对象才能发动。作为对象的墓地的怪兽除外。那之后，作为对象的场上的怪兽直到回合结束时变成和除外的怪兽相同等级，当作调整使用。'),
(49959355, 'Uni-Zombie', '齐唱僵尸', 'ユニゾンビ', 'Tuner Monster', 'Zombie', 'DARK', 3, 1300, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。丢弃1张手卡，作为对象的怪兽的等级上升1星。 ②：以场上1只表侧表示怪兽为对象才能发动。从卡组把1只不死族怪兽送去墓地，作为对象的怪兽的等级上升1星。这个效果的发动后，直到回合结束时不死族以外的自己怪兽不能攻击。'),
(21296383, 'Unibird', '独角鸟', 'ユニバード', 'Effect Monster', 'Winged Beast', 'WIND', 2, 100, 600, '把自己场上表侧表示存在的1只怪兽和这张卡从游戏中除外，从自己墓地选择持有那个原本等级合计数值以下的等级的1只同调怪兽发动。选择的怪兽从墓地特殊召唤。'),
(63595262, 'Unicorn Beacon', '独角兽的引导', 'ユニコーンの導き', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择从游戏中除外的1只5星以下的兽族或者鸟兽族怪兽发动。把1张手卡从游戏中除外，选择的怪兽攻击表示特殊召唤。'),
(57308711, 'Unicycular', '单轮车人', 'アンサイクラー', 'Normal Monster', 'Machine', 'EARTH', 1, 100, 100, '单轮车人是有三轮车人、二轮车人二兄的老三。'),
(95352218, 'Unification', '天下统一', '天下統一', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方的准备阶段时，回合玩家从自己场上的怪兽的等级之内选1个，持有那个等级以外的等级的自己场上表侧表示存在的怪兽全部送去墓地。'),
(34325937, 'Unification of the Cubic Lords', '方界合神', '方界合神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：从自己的手卡·场上把「方界」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：表侧表示的「方界」怪兽被战斗破坏的场合或者从场上离开的场合，把墓地的这张卡除外才能发动。从手卡·卡组把1只4星以下的「方界」怪兽无视召唤条件特殊召唤。这个效果特殊召唤的怪兽在这个回合不会被战斗·效果破坏。'),
(31472884, 'Unified Front', '共斗', '共闘', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己怪兽不能直接攻击。 ①：从手卡丢弃1只怪兽，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成和为这张卡发动而丢弃的怪兽的各自数值相同。'),
(36318200, 'Uniflora, Mystical Beast of the Forest', '森之圣兽 绿叶独角兽', '森の聖獣 ユニフォリア', 'Effect Monster', 'Beast', 'EARTH', 1, 700, 500, '自己墓地的怪兽只有兽族的场合，把这张卡解放才能发动。从自己的手卡·墓地选「森之圣兽 绿叶独角兽」以外的1只兽族怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(56052205, 'Unifrog', '贯青蛙', '貫ガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 400, 400, '这张卡可以直接攻击对方玩家。这张卡直接攻击成功时，自己场上有「贯青蛙」以外的名字带有「青蛙」的怪兽存在的场合，可以把对方场上1张魔法·陷阱卡破坏。'),
(38527680, 'Union Activation', '联合激活', 'ユニオン・アクティベーション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：机械族·光属性的1只通常怪兽或同盟怪兽从手卡·卡组送去墓地，和那只怪兽是攻击力相同而原本卡名不同的1只机械族·光属性怪兽从卡组加入手卡。 ②：这张卡在墓地存在的状态，自己把机械族·光属性怪兽3只同时特殊召唤的场合，把这张卡除外才能发动。从卡组把1只攻击力3000以上的怪兽加入手卡。那之后，进行那1只怪兽的召唤。'),
(60399954, 'Union Attack', '同盟攻击', 'ユニオン・アタック', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。这个回合的战斗阶段开始时，那只怪兽的攻击力直到战斗阶段结束时上升其他的自己场上的攻击表示怪兽的攻击力的合计数值。这个回合，作为对象的怪兽给与对方的战斗伤害变成0，其他的自己怪兽不能攻击。'),
(83152482, 'Union Carrier', '同盟运输车', 'ユニオン・キャリアー', 'Link Monster', 'Machine', 'LIGHT', NULL, 1000, NULL, '种族或者属性相同的怪兽2只 这个卡名的效果1回合只能使用1次。这张卡在连接召唤的回合不能作为连接素材。 ①：以自己场上1只表侧表示怪兽为对象才能发动。从手卡·卡组选原本种族或者原本属性和作为对象的怪兽相同的1只怪兽当作攻击力上升1000的装备卡使用给作为对象的怪兽装备。这个效果从卡组装备的场合，直到回合结束时自己不能把那张装备的怪兽卡以及那些同名怪兽特殊召唤。'),
(300302020, 'Union Combination', NULL, NULL, 'Skill Card', 'Seto Kaiba', NULL, NULL, NULL, NULL, NULL),
(2133971, 'Union Controller', '联合控制器', 'ユニオン・コントローラー', 'Fusion Monster', 'Machine', 'LIGHT', 6, 2200, 1900, '机械族·光属性怪兽＋「Y-机敏龙头」或「Z-无穷履带」 把自己场上的上记的卡除外的场合才能从额外卡组特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：这张卡从额外卡组特殊召唤的场合才能发动。效果文本有「同盟怪兽」记述的1张魔法·陷阱卡从卡组加入手卡。 ②：1回合1次，自己主要阶段才能发动。机械族·光属性的1只通常怪兽或同盟怪兽从手卡特殊召唤。'),
(99249638, 'Union Driver', '同盟驾驶者', 'ユニオン・ドライバー', 'Union Effect Monster', 'Machine', 'LIGHT', 5, 2100, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只表侧表示怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：把装备状态的这张卡除外才能发动。这张卡装备过的怪兽把可以装备的1只4星以下的同盟怪兽当作那个效果的装备魔法卡使用从卡组装备。'),
(66399653, 'Union Hangar', '联合机库', 'ユニオン格納庫', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只机械族·光属性同盟怪兽加入手卡。 ②：1回合1次，自己场上有机械族·光属性同盟怪兽召唤·特殊召唤的场合，以那之内的1只为对象才能发动。从卡组选可以给那只怪兽装备而卡名不同的1只机械族·光属性同盟怪兽给那只怪兽装备。这个效果装备的同盟怪兽在这个回合不能特殊召唤。'),
(89357740, 'Union Pilot', '联合飞行员', 'ユニオン・パイロット', 'Union Effect Monster', 'Machine', 'LIGHT', 5, 2100, 1000, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只效果怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：让装备状态的这张卡回到手卡才能发动。自己1只怪兽把可以装备的除外状态的1只同盟怪兽当作那个效果的装备魔法卡使用来装备，这张卡从自己手卡特殊召唤。'),
(11743119, 'Union Rider', '同盟骑手', 'ユニオン・ライダー', 'Effect Monster', 'Machine', 'WIND', 2, 1000, 1000, '得到对方场上1张处于怪兽状态的同盟怪兽的控制权，装备在这张卡身上。这张卡至多只能以这种方式装备1只同盟怪兽。装备在这张卡身上的同盟怪兽不能以自身效果回复成怪兽状态。'),
(39778366, 'Union Scramble', '急动联合', 'スクランブル・ユニオン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「同盟紧急出动」在1回合只能发动1张。 ①：以除外的自己的机械族·光属性的最多3只通常怪兽或者同盟怪兽为对象才能发动。那些怪兽特殊召唤。 ②：把墓地的这张卡除外，以除外的自己的机械族·光属性的1只通常怪兽或者同盟怪兽为对象才能发动。那只怪兽回到手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(86474024, 'United Front', '共同战线', '共同戦線', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有相同等级的怪兽表侧表示2只以上存在的场合才能发动。陷阱卡的发动无效并破坏。'),
(85936485, 'United Resistance', '团结的反抗军', '団結するレジスタンス', 'Normal Monster', 'Thunder', 'WIND', 3, 1000, 400, '立誓要为了对抗强大力量而集结的人们。革命之日将近。'),
(56747793, 'United We Stand', '团结之力', '団結の力', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽的攻击力·守备力上升自己场上的表侧表示怪兽数量×800。'),
(14731897, 'Unity', '团结 UNITY', '結束 UNITY', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的守备力直到回合结束时变成自己场上的全部表侧表示怪兽的原本守备力合计数值。'),
(53077251, 'Universal Adapter', '单一化', '単一化', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以对方场上1只表侧表示怪兽为对象才能发动。作为对象的怪兽以外的场上的全部怪兽的攻击力直到回合结束时变成和作为对象的怪兽相同。'),
(15310033, 'Unknown Synchron', '未知同步士', 'アンノウン・シンクロン', 'Tuner Monster', 'Machine', 'DARK', 1, NULL, NULL, '「未知同调士」的①的方法的特殊召唤在决斗中只能有1次。 ①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(97360116, 'Unknown Warrior of Fiend', '恶之无名战士', '悪の無名戦士', 'Normal Monster', 'Warrior', 'DARK', 3, 1000, 500, '用敏捷的动作产生真空、切碎对方的战士。'),
(73567374, 'Unleash Your Power!', '力量解放', 'フォース・リリース', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这张卡的发动时自己场上表侧表示存在的全部二重怪兽变成再度召唤的状态。这个效果适用的怪兽在结束阶段时变成里侧守备表示。'),
(25661743, 'Unleashed Power Patron Portal - Terminus', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(300302073, 'Unlocking the Power', NULL, NULL, 'Skill Card', 'Kagemaru', NULL, NULL, NULL, NULL, NULL),
(24218047, 'Unmasked Dragon', '破面龙', '破面竜', 'Effect Monster', 'Wyrm', 'FIRE', 3, 1400, 1100, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只守备力1500以下的幻龙族怪兽特殊召唤。'),
(25704359, 'Unpossessed', '凭依解放', '憑依解放', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己的「灵使」怪兽不会被战斗破坏。 ②：自己的「凭依装着」怪兽的攻击力只在向对方怪兽攻击的伤害计算时上升800。 ③：这张卡在魔法与陷阱区域存在的状态，自己场上的怪兽被战斗·效果破坏的场合才能发动。原本属性和那之内的1只不同的1只守备力1500的魔法师族怪兽从卡组表侧攻击表示或里侧守备表示特殊召唤。'),
(92084010, 'Unshaven Angler', '髭须鮟鱇', 'ヒゲアンコウ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, 1600, '作为水属性怪兽祭品召唤的场合，这只怪兽1只可以作为2只份的祭品使用。'),
(62991886, 'Unstable Evolution', '进化的人类', '進化する人類', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己基本分比对方低的场合，装备怪兽的原本攻击力变成2400。自己基本分比对方高的场合，装备怪兽的原本攻击力变成1000。'),
(87800375, 'Until Noble Arms are Needed Once Again', '圣剑引导的未来', '聖剣の導く未来', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：把自己场上的「圣剑」装备魔法卡数量的卡从自己卡组上面翻开。从那之中选1张加入手卡，剩下的卡用喜欢的顺序回到卡组上面。 ②：把墓地的这张卡除外才能发动。同名卡不在自己的场上·墓地存在的1只「圣骑士」怪兽从卡组特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(72648810, 'Unwavering Bond', '不可动摇的羁绊', '揺るがぬ絆', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：灵摆怪兽的效果或者已在灵摆区域存在的卡的效果由对方发动时才能发动。那个发动无效并除外。'),
(88093706, 'Update Jammer', '更新干扰者', 'アップデートジャマー', 'Link Monster', 'Cyberse', 'WIND', NULL, 2000, NULL, '2星以上的电子界族怪兽2只 ①：自己的电子界族怪兽进行战斗的伤害计算时才能发动1次。直到伤害步骤结束时，场上的其他卡的效果无效化，那次战斗的伤害计算用原本的攻击力·守备力进行。那次战斗让对方怪兽被破坏送去墓地时，给与对方1000伤害。 ②：这张卡作为连接素材送去墓地的场合才能发动。这张卡为连接素材的连接怪兽在这个回合在同1次的战斗阶段中可以作2次攻击。'),
(90557975, 'Updraft', '上升气流', '上昇気流', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把场上存在的雾指示物全部取除发动。给与对方基本分取除的雾指示物数量×300的数值的伤害。'),
(70368879, 'Upstart Goblin', '暴发户格布林', '成金ゴブリン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己从卡组抽1张。那之后，对方回复1000基本分。'),
(58911105, 'Upstart Golden Ninja', '成金忍者', '成金忍者', 'Effect Monster', 'Warrior', 'LIGHT', 4, 500, 1800, '1回合1次，从手卡把1张陷阱卡送去墓地才能发动。从卡组把1只4星以下的名字带有「忍者」的怪兽表侧守备表示或者里侧守备表示特殊召唤。'),
(1784619, 'Uraby', '荒野盗龙', 'ワイルド・ラプター', 'Normal Monster', 'Dinosaur', 'EARTH', 4, 1500, 800, '擅长奔跑的恐龙，利用尖锐的爪子进行攻击。'),
(27753563, 'Uradora of Fate', '命运的里宝牌', '運命のウラドラ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付1000基本分，以自己场上1只表侧表示怪兽为对象才能发动。直到对方回合结束时，那只怪兽的攻击力上升1000，以下效果适用。 ●那只怪兽战斗破坏对方怪兽时才能发动。自己卡组最下面的卡给双方确认，回到卡组最上面或者最下面。确认的卡是龙族·恐龙族·海龙族·幻龙族怪兽的场合，那个攻击力每有1000，自己从卡组抽1张。那之后，自己回复抽出数量×1000基本分。'),
(38844957, 'Urgent Ritual Art', '紧急仪式术', '緊急儀式術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有仪式怪兽存在的场合，从自己的手卡·墓地把1张仪式魔法卡除外才能发动。这张卡的效果变成和那张仪式魔法卡发动时的仪式召唤效果相同。'),
(25274141, 'Urgent Schedule', '紧急时刻表', '緊急ダイヤ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合才能发动。机械族·地属性的1只4星以下的怪兽和1只5星以上的怪兽从卡组效果无效守备表示特殊召唤。这张卡发动的回合，自己不用机械族怪兽不能攻击宣言。 ②：盖放的这张卡被送去墓地的场合才能发动。从卡组把1只机械族·10星怪兽加入手卡。'),
(99002135, 'Urgent Synthesis', '紧急合成', '緊急合成', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '让自己墓地存在的1张「核成兽的钢核」回到卡组发动。从自己的手卡·墓地把1只4星以下的名字带有「核成」的怪兽特殊召唤。'),
(94634433, 'Urgent Tuning', '紧急同调', '緊急同調', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己·对方的战斗阶段才能发动。把1只同调怪兽同调召唤。'),
(6007213, 'Uria, Lord of Searing Flames', '神炎皇乌利亚', '神炎皇ウリア', 'Effect Monster', 'Pyro', 'FIRE', 10, NULL, NULL, '这张卡不能通常召唤。把自己场上3张表侧表示的陷阱卡送去墓地的场合才能特殊召唤。 ①：这张卡的攻击力上升自己墓地的永续陷阱卡数量×1000。 ②：1回合1次，以对方场上1张里侧表示的魔法·陷阱卡为对象才能发动（不能对应这个发动让魔法·陷阱卡发动）。那张里侧表示卡破坏。'),
(89264428, 'Ursarctic Big Dipper', '北斗天熊・大舀取号', 'ベアルクティ・ビッグディッパー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，自己的「北极天熊」怪兽为让效果发动而把怪兽解放的场合，可以作为代替把自己墓地1只7星以上的「北极天熊」怪兽除外。 ②：每次怪兽特殊召唤给这张卡放置1个指示物。 ③：1回合1次，怪兽特殊召唤的场合，把7个以上的这张卡的指示物全部取除，以对方场上1只怪兽为对象才能发动。得到那个控制权。这个效果在场上有「北极天熊」同调怪兽存在的场合才能发动。'),
(16471775, 'Ursarctic Departure', '北斗天熊・出击', 'ベアルクティ・ディパーチャー', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。从卡组把2只「北极天熊」怪兽加入手卡。 ②：自己为让「北极天熊」怪兽的效果发动而把怪兽解放的场合，可以作为代替把墓地的这张卡除外。这个效果在这张卡送去墓地的回合不能使用。'),
(89771220, 'Ursarctic Drytron', '北斗天熊龙机巧极', '天斗輝巧極', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把「北极天熊北斗星」和「龙辉巧-扶筐增二」各1张除外，把1只「天极辉舰-熊斗龙巧」从额外卡组特殊召唤。场上有「北极天熊-勾陈一」或者「龙辉巧-右枢α」存在的场合，也能把要除外的卡之内1张从卡组除外。 ②：自己为让「北极天熊」、「龙辉巧」怪兽的效果发动而把怪兽解放的场合，可以作为代替把墓地的这张卡除外。'),
(80086070, 'Ursarctic Grand Chariot', '北斗天熊－帝车', 'ベアルクティ－グラン＝シャリオ', 'Synchro Monster', 'Beast-Warrior', 'WATER', 7, 2700, 700, '这张卡不能同调召唤，等级差直到7为止从自己场上把8星以上的调整1只和调整以外的同调怪兽1只送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤成功的场合，以这张卡以外的场上最多2张卡为对象才能发动。那些卡破坏。 ②：1回合1次，自己场上的「北极天熊」卡为对象的卡的效果发动时，把自己的手卡·场上1只怪兽解放才能发动。那个发动无效。'),
(81108658, 'Ursarctic Megabilis', '北斗天熊－大灰熊', 'ベアルクティ－メガビリス', 'Tuner Monster', 'Beast-Warrior', 'WATER', 8, 2800, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：自己场上有其他的「北极天熊」怪兽存在的状态，这张卡特殊召唤成功的场合，以对方墓地1张卡为对象才能发动。那张卡除外。'),
(28715905, 'Ursarctic Megapolar', '北斗天熊－大白熊', 'ベアルクティ－メガポーラ', 'Tuner Monster', 'Beast-Warrior', 'WATER', 8, 2500, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：自己场上有其他的「北极天熊」怪兽存在的状态，这张卡特殊召唤成功的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(54700519, 'Ursarctic Megatanus', '北斗天熊－大黑熊', 'ベアルクティ－メガタナス', 'Tuner Monster', 'Beast-Warrior', 'WATER', 8, 2400, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：自己场上有其他的「北极天熊」怪兽存在的状态，这张卡特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。'),
(81321206, 'Ursarctic Mikbilis', '北斗天熊－小灰熊', 'ベアルクティ－ミクビリス', 'Effect Monster', 'Beast', 'WATER', 7, 700, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从手卡把「北极天熊-小灰熊」以外的1只「北极天熊」怪兽特殊召唤。'),
(29537493, 'Ursarctic Mikpolar', '北斗天熊－小白熊', 'ベアルクティ－ミクポーラ', 'Effect Monster', 'Beast', 'WATER', 7, 700, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：这张卡特殊召唤成功的场合才能发动。从卡组把「北极天熊-小白熊」以外的1只「北极天熊」怪兽加入手卡。'),
(55936191, 'Ursarctic Miktanus', '北斗天熊－小黑熊', 'ベアルクティ－ミクタナス', 'Effect Monster', 'Beast', 'WATER', 7, 700, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，从手卡把这张卡以外的1只7星以上的怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。 ②：这张卡特殊召唤成功的场合，以「北极天熊-小黑熊」以外的自己墓地1只「北极天熊」怪兽为对象才能发动。那只怪兽加入手卡。'),
(62714453, 'Ursarctic Polar Star', '北斗天熊－北辰星', 'ベアルクティ－ポーラ＝スター', 'Synchro Monster', 'Machine', 'WATER', 1, 700, 2000, '这张卡不能同调召唤，等级差直到1为止从自己场上把调整1只和调整以外的怪兽1只送去墓地的场合才能特殊召唤。 ①：把这张卡和自己的手卡·场上1只8星「北极天熊」怪兽解放才能发动。把1只7星「北极天熊」同调怪兽无视召唤条件从额外卡组特殊召唤。这个效果特殊召唤的怪兽得到以下效果。 ●对方不能把从额外卡组特殊召唤的持有等级的怪兽的效果发动。'),
(27693363, 'Ursarctic Polari', '北斗天熊－勾陈一', 'ベアルクティ－ポラリィ', 'Synchro Monster', 'Beast', 'WATER', 1, 700, 1000, '这张卡不能同调召唤，等级差直到1为止从自己场上把调整1只和调整以外的怪兽1只送去墓地的场合才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从卡组选1张「北极天熊北斗星」发动。 ②：把自己场上1只7星以上的怪兽解放才能发动。从自己墓地选1只「北极天熊」怪兽加入手卡或特殊召唤。'),
(15758127, 'Ursarctic Quint Charge', '北斗天熊・五倍线充能', 'ベアルクティ・クィントチャージ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，可以支付700基本分，从以下效果选择1个发动。 ●从自己墓地选1只「北极天熊」怪兽加入手卡。 ●自己场上2只「北极天熊」怪兽解放，把持有和那个等级差相同等级的1只「北极天熊」怪兽从额外卡组无视召唤条件特殊召唤。 ②：自己的「北极天熊」同调怪兽被对方的攻击破坏时才能发动。对方直到自身的手卡·场上·墓地的卡合计变成7张为止必须回到持有者卡组。'),
(32692693, 'Ursarctic Radiation', '北斗天熊・放射', 'ベアルクティ・ラディエーション', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动的场合，给这张卡放置7个指示物来发动。 ①：「北极天熊辐射」在自己场上只能有1张表侧表示存在。 ②：每次从手卡·额外卡组有「北极天熊」怪兽特殊召唤，把这张卡1个指示物取除才能发动。自己从卡组抽1张。 ③：自己·对方的结束阶段，以「北极天熊辐射」以外的自己墓地1张「北极天熊」卡为对象才能发动。那张卡回到卡组。'),
(53087962, 'Ursarctic Septentrion', '北斗天熊－柒犍', 'ベアルクティ－セプテン＝トリオン', 'Synchro Monster', 'Beast-Warrior', 'WATER', 7, 3000, 700, '这张卡不能同调召唤，等级差直到7为止从自己场上把8星以上的调整1只和调整以外的同调怪兽1只送去墓地的场合才能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，从额外卡组特殊召唤的不持有等级的表侧表示怪兽的效果无效化。 ②：对方把怪兽特殊召唤的场合才能发动。从卡组把1张「北极天熊」卡加入手卡。'),
(53865474, 'Ursarctic Slider', '北斗天熊・滑翔', 'ベアルクティ・スライダー', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己墓地的怪兽以及除外的自己怪兽之中以1只「北极天熊」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽不能攻击，结束阶段破坏。这张卡的发动后，直到回合结束时自己若非持有等级的怪兽则不能特殊召唤。'),
(47077697, 'Urubonus, the Avatar of Malice', '咒念的化身 乌鲁波努斯', '呪念の化身ウルボヌス', 'Effect Monster', 'Reptile', 'DARK', 5, 2000, 800, '这个卡名的①③的效果1回合各能使用1次。 ①：把自己场上1只爬虫类族怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方场上的怪兽的攻击力·守备力下降300。 ③：把自己场上1只怪兽解放才能发动。对方场上的全部怪兽的攻击力·守备力直到回合结束时下降解放的怪兽的原本攻击力数值。'),
(48649353, 'Ushi Oni', '牛鬼', '牛鬼', 'Normal Monster', 'Fiend', 'DARK', 6, 2150, 1950, '通过黑魔术苏醒的牛之恶魔。从壶中现身。'),
(90884404, 'Utchatzimime Token', '究极幻神 奥特美特尔·比希巴尔金', '究極幻神 アルティミトル・ビシバールキン', 'Token', 'Fiend', NULL, NULL, NULL, NULL, NULL),
(744887, 'Utgarda, Generaider Boss of Delusion', '虚之创王 厄特加沙', '虚の王 ウートガルザ', 'Effect Monster', 'Rock', 'LIGHT', 9, 2200, 2700, '这个卡名的②的效果1回合只能使用1次。 ①：「虚界王战 乌特加德王」在自己场上只能有1只表侧表示存在。 ②：把自己场上的「王战」怪兽或者岩石族怪兽合计2只解放，以场上1张卡为对象才能发动。那张卡除外。这个效果在对方回合也能发动。'),
(30341772, 'Utopia Buster', '希望破坏炮', 'ホープ・バスター', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「希望皇 霍普」的怪兽存在的场合才能发动。对方场上1只攻击力最低的怪兽破坏，给与对方基本分破坏的怪兽的攻击力数值的伤害。'),
(59070329, 'Utopian Aura', '皇之波动', '皇の波動', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1个超量素材取除发动。自己场上表侧表示存在的超量怪兽直到结束阶段时不会被卡的效果破坏。'),
(8512558, 'Utopic Onomatopoeia', '希望皇拟声乌托邦', '希望皇オノマトピア', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1500, 1500, '这个卡名在规则上也当作「刷拉拉」、「我我我」、「隆隆隆」、「怒怒怒」卡使用。这个卡名的效果1回合只能使用1次。 ①：自己主要阶段才能发动。从手卡把「希望皇 拟声乌托邦」以外的以下怪兽各最多1只守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。 ●「刷拉拉」怪兽 ●「我我我」怪兽 ●「隆隆隆」怪兽 ●「怒怒怒」怪兽'),
(57566760, 'Uzuhime the Manifested Mikanko', '贵日女之御巫', 'ウズヒメの御巫', 'XYZ Monster', 'Fairy', 'LIGHT', 3, NULL, NULL, '3星「御巫」怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。从自己的卡组·墓地把1张装备魔法卡加入手卡。 ②：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ③：这张卡进行攻击的伤害步骤结束时，把这张卡1个超量素材取除才能发动。这张卡可以继续攻击。'),
(33725002, 'V Salamander', 'V火精灵', 'Vサラマンダー', 'Effect Monster', 'Spellcaster', 'FIRE', 4, 1500, 1300, '这张卡召唤成功时，可以选择自己墓地1只名字带有「希望皇 霍普」的怪兽特殊召唤。自己的主要阶段时，场上的这只怪兽可以给自己的「混沌No.39 希望皇 霍普雷V」装备。这张卡装备中的场合，1回合1次，把装备怪兽1个超量素材取除才能发动。装备怪兽的效果无效，对方场上的怪兽全部破坏，给与对方基本分那个数量×1000的数值的伤害。'),
(13536606, 'V-LAN Hydra', 'V-LAN多头蛇', 'V－LAN ヒドラ', 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1900, NULL, '衍生物以外的怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升和这张卡互相连接的怪兽数量×300。 ②：以这张卡所互相连接区1只连接3以下的怪兽为对象才能发动。那只怪兽解放，那个连接标记数量的「V-LAN衍生物」（电子界族·光·1星·攻/守0）在自己场上特殊召唤。这个回合自己不能把连接标记数量和作为对象的怪兽相同的怪兽特殊召唤。'),
(13536607, 'V-LAN Token', 'V-LAN多头蛇', 'V－LAN ヒドラ', 'Token', 'Cyberse', NULL, NULL, NULL, NULL, NULL),
(51638941, 'V-Tiger Jet', 'V-喷气虎', 'V－タイガー・ジェット', 'Normal Monster', 'Machine', 'LIGHT', 4, 1600, 1800, '擅长空中战，具备合体能力的怪兽。驱使合体和分离施展立体攻击。'),
(31971040, 'Vaalmonica Chosen Melody', '选律之华耳琴璃', '選律のヴァルモニカ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「异响鸣」怪兽卡存在的场合，从以下效果选1个适用。自己场上有「异响鸣」连接怪兽存在的场合，可以选两方适用。 ●自己回复500基本分。这个回合中，对方不能把自己场上的「异响鸣」怪兽卡作为效果的对象。 ●自己受到500伤害。那之后，可以把对方场上1只效果怪兽的效果直到回合结束时无效。'),
(98167225, 'Vaalmonica Creation', '创神之华耳琴璃', '創神のヴァルモニカ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有响鸣指示物6个以上存在，自己场上的「异响鸣」连接怪兽的攻击力上升1200。 ②：对方把怪兽特殊召唤的场合才能发动。进行1只「异响鸣」连接怪兽的连接召唤。 ③：这张卡从手卡·场上送去墓地的场合才能发动。给可以放置响鸣指示物的自己的灵摆区域1张卡放置响鸣指示物到变成3个。'),
(65496951, 'Vaalmonica Disarmonia', '华耳琴璃・不和谐音', 'ヴァルモニカ・ディサルモニア', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：给可以放置响鸣指示物的自己的灵摆区域1张卡放置1个响鸣指示物。那之后，从以下效果选1个适用。 ●自己回复500基本分。那之后，可以把「异响鸣的不调和」以外的自己的除外状态的1张「异响鸣」卡加入手卡。 ●自己受到500伤害。那之后，可以把「异响鸣的不调和」以外的自己墓地1张「异响鸣」卡加入手卡。'),
(14972952, 'Vaalmonica Ereditare', '华耳琴璃・承继', 'ヴァルモニカ・エレディターレ', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「异响鸣」连接怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。 ②：把墓地的这张卡除外才能发动。让最多有自己场上的响鸣指示物数量的「异响鸣的继承」以外的自己的额外卡组（表侧）·墓地·除外状态的「异响鸣」卡回到卡组。那之后，自己可以抽出回去的卡每3张为1张的数量。'),
(4582942, 'Vaalmonica Followed Rhythm', '律导之华耳琴璃', '律導のヴァルモニカ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「异响鸣」怪兽卡存在的场合，从以下效果选1个适用。自己场上有「异响鸣」连接怪兽存在的场合，可以选两方适用。 ●自己回复500基本分。那之后，可以把场上1张魔法·陷阱卡破坏。 ●自己受到500伤害。那之后，可以让场上1只怪兽回到手卡。'),
(78598237, 'Vaalmonica Intonare', '华耳琴璃・调音', 'ヴァルモニカ・イントナーレ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。 ●自己回复500基本分。可以特殊召唤的怪兽在自己墓地存在的场合，再让那之内的1只由对方选出，那只怪兽在自己场上特殊召唤。 ●自己受到500伤害。那之后，可以从自己墓地把1只4星怪兽加入手卡。'),
(38491852, 'Vaalmonica Invitare', '华耳琴璃・邀请', 'ヴァルモニカ・インヴィターレ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从以下效果选1个适用。 ●从卡组把1只「异响鸣」怪兽特殊召唤。这张卡的发动后，直到回合结束时自己不能把「异响鸣」怪兽以外的场上的怪兽的效果发动。 ●自己场上有灵摆怪兽以外的「异响鸣」怪兽存在的场合，从卡组选2只卡名不同的「异响鸣」灵摆怪兽，那之内的1只加入手卡，另1只表侧加入额外卡组。'),
(5605529, 'Vaalmonica Scelta', '华耳琴璃・抉择', 'ヴァルモニカ・シェルタ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。 ●自己回复500基本分。那之后，可以选自己1张手卡回到卡组最下面。那个场合，自己抽2张。 ●自己受到500伤害。那之后，可以从卡组把「异响鸣的选择」以外的1张「异响鸣」魔法·陷阱卡加入手卡。'),
(42193638, 'Vaalmonica Versare', '华耳琴璃・倾注', 'ヴァルモニカ・ヴェルサーレ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从以下效果选1个适用。自己的灵摆区域没有「异响鸣」卡存在的场合，适用的效果由对方来选。 ●自己回复500基本分。那之后，可以直到「异响鸣」卡出现为止从自己卡组上面翻卡。那个场合，翻开的「异响鸣」卡加入手卡，剩余回到卡组。 ●自己受到500伤害。那之后，可以从卡组把「异响鸣的倒水」以外的1张「异响鸣」卡送去墓地。'),
(39210885, 'Vaalmonica, the Agathokakological Voice', '天魔之声选器－『华耳琴璃』', '天魔の聲選器－『ヴァルモニカ』', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「异响鸣」怪兽加入手卡。 ②：自己的灵摆区域的卡有响鸣指示物被放置，那卡的响鸣指示物变成3个的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽不能攻击宣言。'),
(9839115, 'Vagnawa the Moon-Eating Dragon', '月朦龙 巴格那瓦', '月朧龍ヴァグナワ', 'Synchro Monster', 'Dragon', 'DARK', 7, 1500, 1500, '调整＋调整以外的怪兽1只以上 这个卡名的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。这张卡的攻击力直到下个回合的结束时上升那些作为同调素材的除调整以外的怪兽的等级合计×300。那之后，给与对方那只作为同调素材的调整的等级×300伤害。'),
(9929399, 'Vague Shadow Token', '黑羽-胧影之业风', 'BF－朧影のゴウフウ', 'Token', 'Winged Beast', NULL, NULL, NULL, NULL, NULL),
(61272280, 'Vahram, the Magistus Divinity Dragon', '伟魔龙神 绝火之瓦尔弗兰', '絶火の竜神ヴァフラム', 'Synchro Monster', 'Dragon', 'FIRE', 8, 2500, 2900, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：同调召唤的这张卡被破坏的场合才能发动。对方场上的表侧表示的卡全部破坏。 ②：有这张卡装备的怪兽不会被对方的魔法·陷阱卡的效果破坏。 ③：有这张卡装备的怪兽和对方怪兽进行战斗的伤害步骤开始时才能发动。那只对方怪兽破坏。'),
(94933468, 'Vain Betrayer', '枉然-背叛的嘲笑', 'Vain－裏切りの嘲笑', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方场上的超量怪兽攻击宣言时，选择那1只怪兽才能发动。选择的怪兽不能攻击，效果无效化。只要选择的怪兽在场上存在，每次对方的结束阶段从对方卡组上面把3张卡送去墓地。选择的怪兽从场上离开时，这张卡破坏。'),
(91749600, 'Vala, Seidhr of the Generaider Bosses', '创王之咒 渥尔娃', '王の呪 ヴァラ', 'Effect Monster', 'Fairy', 'FIRE', 9, 2500, 2500, '这个卡名的②③的效果1回合各能使用1次。 ①：「王战之咒 伐拉」在自己场上只能有1只表侧表示存在。 ②：这张卡在手卡·墓地存在的场合，从手卡把1张其他的「王战」卡送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ③：这张卡特殊召唤成功的场合才能发动。从自己的手卡·墓地选「王战之咒 伐拉」以外的1只「王战」怪兽特殊召唤。'),
(24096499, 'Valerifawn, Mystical Beast of the Forest', '森之圣兽 缬草小鹿', '森の聖獣 ヴァレリフォーン', 'Tuner Monster', 'Beast', 'EARTH', 2, 400, 900, '「森之圣兽 缬草小鹿」的效果1回合只能使用1次。 ①：丢弃1张手卡，以「森之圣兽 缬草小鹿」以外的自己墓地1只2星以下的兽族怪兽为对象才能发动。那只怪兽表侧攻击表示或者里侧守备表示特殊召唤。');